// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt. Scoped CSS is precompiled.
"use client";
import * as React from "react";
import { cn } from "./utils";
function Table({ className, ...props }: React.ComponentProps<"table">) {
  return (
    <div
      data-slot="table-container"
      className={cn(
        "roc-shadcn",
        "roc-u-relative roc-u-w-full roc-u-overflow-x-auto",
      )}
    >
      <table
        data-slot="table"
        className={cn(
          "roc-shadcn",
          cn(
            "roc-u-w-full roc-u-caption-bottom roc-u-text-sm",
            className,
          ),
        )}
        {...props}
      />
    </div>
  );
}
function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  return (
    <thead
      data-slot="table-header"
      className={cn("roc-shadcn", cn("roc-u-[&_tr]:border-b", className))}
      {...props}
    />
  );
}
function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("roc-shadcn", cn("roc-u-[&_tr:last-child]:border-0", className))}
      {...props}
    />
  );
}
function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-border-t roc-u-bg-muted/50 roc-u-font-medium roc-u-[&>tr]:last:border-b-0",
          className,
        ),
      )}
      {...props}
    />
  );
}
function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-border-b roc-u-transition-colors roc-u-hover:bg-muted/50 roc-u-has-aria-expanded:bg-muted/50 roc-u-data-[state=selected]:bg-muted",
          className,
        ),
      )}
      {...props}
    />
  );
}
function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-h-10 roc-u-px-2 roc-u-text-left roc-u-align-middle roc-u-font-medium roc-u-whitespace-nowrap roc-u-text-foreground roc-u-[&:has([role=checkbox])]:pr-0 roc-u-[&>[role=checkbox]]:translate-y-[2px]",
          className,
        ),
      )}
      {...props}
    />
  );
}
function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-p-2 roc-u-align-middle roc-u-whitespace-nowrap roc-u-[&:has([role=checkbox])]:pr-0 roc-u-[&>[role=checkbox]]:translate-y-[2px]",
          className,
        ),
      )}
      {...props}
    />
  );
}
function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-mt-4 roc-u-text-sm roc-u-text-muted-foreground",
          className,
        ),
      )}
      {...props}
    />
  );
}
export {
  Table,
  TableHeader,
  TableBody,
  TableFooter,
  TableHead,
  TableRow,
  TableCell,
  TableCaption,
};

import "./table.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./shadcn-base.css";
/*! tailwindcss v4.3.3 | MIT License | https://tailwindcss.com */
@layer properties;
.roc-shadcn {
  --roc-sh-spacing: 0.25rem;
  --roc-sh-text-sm: 0.875rem;
  --roc-sh-text-sm--line-height: calc(1.25 / 0.875);
  --roc-sh-font-weight-medium: 500;
  --roc-sh-default-transition-duration: 150ms;
  --roc-sh-default-transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}
.roc-u-relative {
  position: relative;
}
.roc-u-mt-4 {
  margin-top: calc(var(--roc-sh-spacing) * 4);
}
.roc-u-h-10 {
  height: calc(var(--roc-sh-spacing) * 10);
}
.roc-u-w-full {
  width: 100%;
}
.roc-u-caption-bottom {
  caption-side: bottom;
}
.roc-u-overflow-x-auto {
  overflow-x: auto;
}
.roc-u-border-t {
  border-top-style: var(--roc-sh-tw-border-style);
  border-top-width: 1px;
}
.roc-u-border-b {
  border-bottom-style: var(--roc-sh-tw-border-style);
  border-bottom-width: 1px;
}
.roc-u-bg-muted\/50 {
  background-color: color-mix(in srgb, #f5f5f5 50%, transparent);
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(
      in oklab,
      var(--roc-sh-color-muted) 50%,
      transparent
    );
  }
}
.roc-u-p-2 {
  padding: calc(var(--roc-sh-spacing) * 2);
}
.roc-u-px-2 {
  padding-inline: calc(var(--roc-sh-spacing) * 2);
}
.roc-u-text-left {
  text-align: left;
}
.roc-u-align-middle {
  vertical-align: middle;
}
.roc-u-text-sm {
  font-size: var(--roc-sh-text-sm);
  line-height: var(--roc-sh-tw-leading, var(--roc-sh-text-sm--line-height));
}
.roc-u-font-medium {
  --roc-sh-tw-font-weight: var(--roc-sh-font-weight-medium);
  font-weight: var(--roc-sh-font-weight-medium);
}
.roc-u-whitespace-nowrap {
  white-space: nowrap;
}
.roc-u-text-foreground {
  color: var(--roc-sh-color-foreground);
}
.roc-u-text-muted-foreground {
  color: var(--roc-sh-color-muted-foreground);
}
.roc-u-transition-colors {
  transition-property:
    color, background-color, border-color, outline-color, text-decoration-color,
    fill, stroke, --roc-sh-tw-gradient-from, --roc-sh-tw-gradient-via,
    --roc-sh-tw-gradient-to;
  transition-timing-function: var(
    --roc-sh-tw-ease,
    var(--roc-sh-default-transition-timing-function)
  );
  transition-duration: var(
    --roc-sh-tw-duration,
    var(--roc-sh-default-transition-duration)
  );
}
@media (hover: hover) {
  .roc-u-hover\:bg-muted\/50:hover {
    background-color: color-mix(in srgb, #f5f5f5 50%, transparent);
  }
  @supports (color: color-mix(in lab, red, red)) {
    .roc-u-hover\:bg-muted\/50:hover {
      background-color: color-mix(
        in oklab,
        var(--roc-sh-color-muted) 50%,
        transparent
      );
    }
  }
}
.roc-u-has-aria-expanded\:bg-muted\/50:has([aria-expanded="true"]) {
  background-color: color-mix(in srgb, #f5f5f5 50%, transparent);
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(
      in oklab,
      var(--roc-sh-color-muted) 50%,
      transparent
    );
  }
}
.roc-u-data-\[state\=selected\]\:bg-muted[data-state="selected"] {
  background-color: var(--roc-sh-color-muted);
}
.roc-u-\[\&_tr\]\:border-b tr {
  border-bottom-style: var(--roc-sh-tw-border-style);
  border-bottom-width: 1px;
}
.roc-u-\[\&_tr\:last-child\]\:border-0 tr:last-child {
  border-style: var(--roc-sh-tw-border-style);
  border-width: 0px;
}
.roc-u-\[\&\:has\(\[role\=checkbox\]\)\]\:pr-0:has([role="checkbox"]) {
  padding-right: 0px;
}
.roc-u-\[\&\>\[role\=checkbox\]\]\:translate-y-\[2px\] > [role="checkbox"] {
  --roc-sh-tw-translate-y: 2px;
  translate: var(--roc-sh-tw-translate-x) var(--roc-sh-tw-translate-y);
}
.roc-u-\[\&\>tr\]\:last\:border-b-0 > tr:last-child {
  border-bottom-style: var(--roc-sh-tw-border-style);
  border-bottom-width: 0px;
}
@property --roc-sh-tw-border-style {
  syntax: "*";
  inherits: false;
  initial-value: solid;
}
@property --roc-sh-tw-font-weight {
  syntax: "*";
  inherits: false;
}
@property --roc-sh-tw-translate-x {
  syntax: "*";
  inherits: false;
  initial-value: 0;
}
@property --roc-sh-tw-translate-y {
  syntax: "*";
  inherits: false;
  initial-value: 0;
}
@property --roc-sh-tw-translate-z {
  syntax: "*";
  inherits: false;
  initial-value: 0;
}
@layer properties {
  @supports ((-webkit-hyphens: none) and (not (margin-trim: inline))) or
    ((-moz-orient: inline) and (not (color: rgb(from red r g b)))) {
    :where(
      .roc-shadcn,
      .roc-shadcn *,
      .roc-shadcn::before,
      .roc-shadcn::after
    ) {
      --roc-sh-tw-border-style: solid;
      --roc-sh-tw-font-weight: initial;
      --roc-sh-tw-translate-x: 0;
      --roc-sh-tw-translate-y: 0;
      --roc-sh-tw-translate-z: 0;
    }
  }
}

/* Scoped preflight for copied components. No selectors affect the host page. */
@import "./ui-base.css";
:where(.roc-shadcn, .roc-shadcn *, .roc-shadcn::before, .roc-shadcn::after) {
  box-sizing: border-box;
  border-width: 0;
  border-style: solid;
  border-color: var(--roc-line, #e5e5e5);
}
:where(.roc-shadcn) {
  font-family: inherit;
  line-height: 1.5;
  color: var(--roc-ink, #252525);
  /* One place maps the ROC design tokens (ink, paper, line, muted, marker, focus, accent, radius)
     onto the shadcn-named variables every copied component reads. */
  --roc-sh-radius-xs: max(0px, calc(var(--roc-radius, 9px) - 6px));
  --roc-sh-radius-sm: max(0px, calc(var(--roc-radius, 9px) - 4px));
  --roc-sh-radius-md: max(0px, calc(var(--roc-radius, 9px) - 2px));
  --roc-sh-radius-lg: var(--roc-radius, 9px);
  --roc-sh-radius-xl: calc(var(--roc-radius, 9px) + 3px);
  --roc-sh-color-background: var(--roc-paper, #fff);
  --roc-sh-color-foreground: var(--roc-ink, #252525);
  --roc-sh-color-card: var(--roc-paper, #fff);
  --roc-sh-color-card-foreground: var(--roc-ink, #252525);
  --roc-sh-color-popover: var(--roc-paper, #fff);
  --roc-sh-color-popover-foreground: var(--roc-ink, #252525);
  --roc-sh-color-muted: color-mix(in srgb, var(--roc-ink, #252525) 4%, var(--roc-paper, #fff));
  --roc-sh-color-muted-foreground: var(--roc-muted, #737373);
  --roc-sh-color-accent: var(--roc-marker, #f3f3f3);
  --roc-sh-color-accent-foreground: var(--roc-ink, #252525);
  --roc-sh-color-secondary: var(--roc-marker, #f3f3f3);
  --roc-sh-color-secondary-foreground: var(--roc-ink, #252525);
  --roc-sh-color-border: var(--roc-line, #e5e5e5);
  --roc-sh-color-input: var(--roc-line, #dedede);
  --roc-sh-color-ring: var(--roc-focus, #737373);
  --roc-sh-color-primary: var(--roc-accent, var(--roc-ink, #252525));
  --roc-sh-color-primary-foreground: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
:where(
  button.roc-shadcn,
  input.roc-shadcn,
  select.roc-shadcn,
  textarea.roc-shadcn
) {
  font: inherit;
  color: inherit;
  background: transparent;
}
:where(button.roc-shadcn) {
  cursor: pointer;
}
:where(button.roc-shadcn:disabled) {
  cursor: not-allowed;
}
:where(
  .roc-shadcn h1,
  .roc-shadcn h2,
  .roc-shadcn h3,
  .roc-shadcn p,
  .roc-shadcn pre,
  h1.roc-shadcn,
  h2.roc-shadcn,
  h3.roc-shadcn,
  p.roc-shadcn,
  pre.roc-shadcn
) {
  margin: 0;
}
:where(ul.roc-shadcn, ol.roc-shadcn) {
  list-style: none;
  margin: 0;
  padding: 0;
}
:where(.roc-shadcn svg) {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
:where(.roc-shadcn input) {
  min-width: 0;
}
.roc-shadcn:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .roc-shadcn,
  .roc-shadcn * {
    scroll-behavior: auto !important;
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

.roc-shadcn[hidden],
.roc-shadcn [hidden] {
  display: none !important;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
